const express = require('express');
const db = require('../db');

const router = express.Router();

// Anonymous. No session is read here and nothing on the page varies by user -
// price, stock and copy are the same for everybody. Catalogue rows change when
// someone edits a product in the admin tool, which is a few times a day.
router.get('/:slug', async (req, res) => {
  const product = await db.productBySlug(req.params.slug);
  if (!product) return res.status(404).send('not found');
  const related = await db.relatedProducts(product.id);
  const stock = await db.stockFor(product.id);
  // Overrides the app-wide no-store from middleware/security.js so the CDN can
  // cache this page. Only set on success, so 404s and errors stay uncached.
  // Stock and admin edits show up within a minute.
  res.set('Cache-Control', 'public, max-age=60, stale-while-revalidate=60');
  res.removeHeader('Pragma');
  res.render('product', { product, related, stock });
});

module.exports = router;

ratelimit.js.text:
const { client } = require("./redis");

// Requests per client per minute, summed across every worker on every box.
// Counted in the shared Redis because each worker's memory is private (app.js).
const LIMIT = Number(process.env.RATE_LIMIT_PER_MINUTE) || 600;

// Runs after auth: keyed by client_id, not IP, since one client calls from many
// addresses and many clients share a NAT.
// ponytail: fixed one-minute window, so a client can burst up to 2x LIMIT
// across a window boundary; move to a sliding window if that matters.
async function rateLimit(req, res, next) {
  const now = Date.now();
  const window = Math.floor(now / 60000);
  const key = `rl:${req.client.client_id}:${window}`;
  let count;
  try {
    [[, count]] = await client.multi().incr(key).expire(key, 60).exec();
  } catch (err) {
    // Fail open: a Redis hiccup should not take /v1 down for everyone.
    return next();
  }
  if (count > LIMIT) {
    res.set("Retry-After", String(Math.ceil(((window + 1) * 60000 - now) / 1000)));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit };

