// Run with: node ratelimit.test.js (no Redis needed; it is faked below).
const assert = require("assert");

const store = new Map();
let redisDown = false;
const fakeClient = {
  multi() {
    let key;
    const chain = {
      incr(k) { key = k; return chain; },
      expire() { return chain; },
      async exec() {
        if (redisDown) throw new Error("ECONNREFUSED");
        store.set(key, (store.get(key) || 0) + 1);
        return [[null, store.get(key)], [null, 1]];
      },
    };
    return chain;
  },
};
require.cache[require.resolve("./redis")] = { loaded: true, exports: { client: fakeClient } };
process.env.RATE_LIMIT_PER_MINUTE = "3";
Date.now = () => 1700000030000; // 10s before a window boundary
const { rateLimit } = require("./ratelimit");

function call(clientId) {
  return new Promise((resolve) => {
    const headers = {};
    const res = {
      set: (k, v) => { headers[k] = v; },
      status: (code) => ({ end: () => resolve({ code, headers }) }),
    };
    rateLimit({ client: { client_id: clientId } }, res, () => resolve({ code: "next" }));
  });
}

(async () => {
  for (let i = 0; i < 3; i++) assert.strictEqual((await call("a")).code, "next");
  const blocked = await call("a");
  assert.strictEqual(blocked.code, 429);
  assert.strictEqual(blocked.headers["Retry-After"], "10");
  assert.strictEqual((await call("b")).code, "next"); // other clients unaffected
  redisDown = true;
  assert.strictEqual((await call("a")).code, "next"); // fails open
  console.log("ok");
})();

