rateLimit.js.text:
const { client } = require("./redis");

// Counters live in the shared Redis, not in module scope: a client's requests
// are spread across every worker on every box, so a per-process count would
// let each client through WORKERS x boxes times the limit.
const LIMIT = Number(process.env.RATE_LIMIT_REQUESTS) || 600;
const WINDOW_MS = Number(process.env.RATE_LIMIT_WINDOW_MS) || 60_000;

// Fixed window per client. INCR and the expiry run as one script so a counter
// can never be left behind without a TTL.
client.defineCommand("rateLimitHit", {
  numberOfKeys: 1,
  lua: `
    local count = redis.call("INCR", KEYS[1])
    local ttl = redis.call("PTTL", KEYS[1])
    if ttl < 0 then
      redis.call("PEXPIRE", KEYS[1], ARGV[1])
      ttl = tonumber(ARGV[1])
    end
    return { count, ttl }
  `,
});

// Mount after authentication. It keys on the client account rather than the
// API key or the address: one client may hold several keys and call from many
// addresses, and unrelated clients share an address behind a NAT.
async function rateLimit(req, res, next) {
  let count, ttl;
  try {
    [count, ttl] = await client.rateLimitHit(`rl:${req.client.client_id}`, WINDOW_MS);
  } catch (err) {
    // Fail open: a Redis problem should not turn into an outage for everyone.
    console.error("rate limit check failed", err);
    return next();
  }

  const resetSeconds = Math.ceil(ttl / 1000);
  res.set("RateLimit-Limit", String(LIMIT));
  res.set("RateLimit-Remaining", String(Math.max(0, LIMIT - count)));
  res.set("RateLimit-Reset", String(resetSeconds));

  if (count > LIMIT) {
    res.set("Retry-After", String(resetSeconds));
    return res.status(429).json({ error: "rate_limited" });
  }
  next();
}

module.exports = rateLimit;

