const https = require("https");

const PROVIDER = "api.cardstream.example";
const ATTEMPTS = 3;

// Retrying is only safe because every attempt sends the same Idempotency-Key:
// a timed-out charge may have gone through, and the provider then returns that
// charge instead of authorising again. Declines (4xx) are final.
async function charge(params) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await attemptCharge(params);
    } catch (err) {
      if (!isUnknown(err) || attempt === ATTEMPTS) throw err;
      await new Promise((r) => setTimeout(r, 500 * 2 ** attempt));
    }
  }
}

// No response, or a 5xx: the card may or may not have been charged.
function isUnknown(err) {
  return !err.statusCode || err.statusCode >= 500;
}

function attemptCharge({ amountCents, currency, customerId, source, idempotencyKey }) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            const err = new Error(data);
            err.statusCode = res.statusCode;
            return reject(err);
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

module.exports = { charge, isUnknown };

