const assert = require("assert");
const https = require("https");
const { EventEmitter } = require("events");
const payments = require("./payments");

// Each entry is "timeout" or { status, body }; returns the Idempotency-Key of every call.
function fakeProvider(responses) {
  const keys = [];
  https.request = (opts, onResponse) => {
    keys.push(opts.headers["Idempotency-Key"]);
    const req = new EventEmitter();
    req.destroy = (err) => req.emit("error", err);
    req.end = () =>
      setImmediate(() => {
        const r = responses.shift();
        if (r === "timeout") return req.emit("timeout");
        const res = new EventEmitter();
        res.statusCode = r.status;
        onResponse(res);
        res.emit("data", JSON.stringify(r.body));
        res.emit("end");
      });
    return req;
  };
  return keys;
}

(async () => {
  let keys = fakeProvider(["timeout", "timeout", { status: 200, body: { id: "ch_1" } }]);
  assert.strictEqual((await payments.charge({ idempotencyKey: "k1" })).id, "ch_1");
  assert.deepStrictEqual(keys, ["k1", "k1", "k1"]);

  keys = fakeProvider([{ status: 402, body: { error: "declined" } }]);
  await assert.rejects(payments.charge({ idempotencyKey: "k2" }), (e) => !payments.isUnknown(e));
  assert.strictEqual(keys.length, 1);

  keys = fakeProvider(["timeout", "timeout", "timeout"]);
  await assert.rejects(payments.charge({ idempotencyKey: "k3" }), payments.isUnknown);
  assert.strictEqual(keys.length, 3);

  console.log("ok");
})();

routes/checkout.js.text:
const crypto = require("crypto");
const express = require("express");
const db = require("../db");
const payments = require("../payments");

const router = express.Router();

router.post("/:orderId/pay", async (req, res) => {
  const rows = await db.query(
    "SELECT id, total_cents, currency, customer_id, status FROM orders WHERE id = $1",
    [req.params.orderId]
  );
  if (!rows.length) return res.status(404).end();
  const order = rows[0];
  if (order.status !== "pending") return res.status(409).json({ status: order.status });

  try {
    const charge = await payments.charge({
      amountCents: order.total_cents,
      currency: order.currency,
      customerId: order.customer_id,
      source: req.body.source,
      // Same order and card always gives the same key, so paying again after an
      // unknown outcome returns the original charge; a different card gets a new one.
      idempotencyKey: crypto
        .createHash("sha256")
        .update(JSON.stringify([order.id, req.body.source]))
        .digest("hex"),
    });
    await db.query(
      "UPDATE orders SET status = 'paid', charge_id = $2 WHERE id = $1",
      [order.id, charge.id]
    );
    res.json({ status: "paid", charge: charge.id });
  } catch (err) {
    // Timed out even after retries: the order stays pending and the customer
    // can safely pay again, which resends the same key.
    if (payments.isUnknown(err)) return res.status(504).json({ status: "unknown" });
    res.status(502).json({ error: "payment failed" });
  }
});

module.exports = router;

