ratelimit.js.text:
// Fixed-window limit per client account. The count lives in the shared Redis,
// not in module scope, so the limit holds across every worker on every box.
// ponytail: one limit for every plan; read it off req.client.plan when plans need different ceilings.
const LIMIT = 600;
const WINDOW_SECONDS = 60;

function rateLimit(redis) {
  return async (req, res, next) => {
    const now = Math.floor(Date.now() / 1000);
    const key = `rl:${req.client.client_id}:${Math.floor(now / WINDOW_SECONDS)}`;
    let count;
    try {
      [[, count]] = await redis.multi().incr(key).expire(key, WINDOW_SECONDS).exec();
    } catch (err) {
      // Fail open: a Redis outage shouldn't take /v1 down with it.
      return next();
    }
    if (count > LIMIT) {
      res.set("Retry-After", String(WINDOW_SECONDS - (now % WINDOW_SECONDS)));
      return res.status(429).end();
    }
    next();
  };
}

module.exports = rateLimit;
module.exports.LIMIT = LIMIT;

