// node ratelimit.test.js
const assert = require("assert");
const rateLimit = require("./ratelimit");

const store = new Map();
const fakeRedis = {
  multi() {
    const ops = [];
    const m = {
      incr(k) { ops.push(() => store.set(k, (store.get(k) || 0) + 1).get(k)); return m; },
      expire() { ops.push(() => 1); return m; },
      exec: async () => ops.map((op) => [null, op()]),
    };
    return m;
  },
};

async function call(limiter, clientId) {
  const res = { code: 200, headers: {} };
  res.set = (k, v) => { res.headers[k] = v; return res; };
  res.status = (c) => { res.code = c; return res; };
  res.end = () => res;
  let passed = false;
  await limiter({ client: { client_id: clientId } }, res, () => { passed = true; });
  return { passed, res };
}

(async () => {
  const limiter = rateLimit(fakeRedis);
  for (let i = 0; i < rateLimit.LIMIT; i++) assert((await call(limiter, "noisy")).passed);

  const over = await call(limiter, "noisy");
  assert(!over.passed);
  assert.strictEqual(over.res.code, 429);
  assert(Number(over.res.headers["Retry-After"]) > 0);

  assert((await call(limiter, "quiet")).passed, "other clients unaffected");

  const broken = { multi() { throw new Error("redis down"); } };
  assert((await call(rateLimit(broken), "noisy")).passed, "fails open");

  console.log("ok");
})();

