rateLimit.js.text:
const { client } = require("./redis");

// Counted in Redis, not in process memory: with four workers per box and
// several boxes, a per-process counter would let a client through at many
// times the limit.
const WINDOW_MS = 60 * 1000;
const LIMIT = Number(process.env.RATE_LIMIT_PER_MINUTE) || 300;

// Increment and expiry in one script, so a counter can never be left without
// an expiry and block a client forever.
client.defineCommand("rateLimitHit", {
  numberOfKeys: 1,
  lua: `
    local n = redis.call("INCR", KEYS[1])
    local ttl = redis.call("PTTL", KEYS[1])
    if ttl < 0 then
      redis.call("PEXPIRE", KEYS[1], ARGV[1])
      ttl = tonumber(ARGV[1])
    end
    return {n, ttl}
  `,
});

// Keyed by client, not by IP: one client calls from many addresses, and
// several clients share an address behind NAT. Must run after the API key
// lookup has set req.client.
async function rateLimit(req, res, next) {
  let count, ttl;
  try {
    [count, ttl] = await client.rateLimitHit(`rl:${req.client.client_id}`, WINDOW_MS);
  } catch (err) {
    // Fail open: a Redis outage should not take /v1 down with it.
    return next();
  }
  const resetSeconds = String(Math.ceil(ttl / 1000));
  res.set("RateLimit-Limit", String(LIMIT));
  res.set("RateLimit-Remaining", String(Math.max(0, LIMIT - count)));
  res.set("RateLimit-Reset", resetSeconds);
  if (count > LIMIT) {
    res.set("Retry-After", resetSeconds);
    return res.status(429).end();
  }
  next();
}

module.exports = rateLimit;

