});

// Keyed by client, not by IP: one client calls from many addresses, and
// several clients share an address behind NAT. Must run after the API key
// lookup has set req.client.
async function rateLimit(req, res, next) {
  let count, ttl;
  try {
    [count, ttl] = await client.rateLimitHit(`rl:${req.client.client_id}`, WINDOW_MS);
  } catch (err) {
    // Fail open: a Redis outage should not take /v1 down with it.
    return next();
  }
  const resetSeconds = String(Math.ceil(ttl / 1000));
  res.set("RateLimit-Limit", String(LIMIT));
  res.set("RateLimit-Remaining", String(Math.max(0, LIMIT - count)));
  res.set("RateLimit-Reset", resetSeconds);
  if (count > LIMIT) {
    res.set("Retry-After", resetSeconds);
    return res.status(429).end();
  }
  next();
}

module.exports = rateLimit;

