const crypto = require("crypto");
const https = require("https");
const { setTimeout: sleep } = require("timers/promises");

const PROVIDER = "api.cardstream.example";
const RETRY_DELAYS_MS = [500, 2000];

// Retries timeouts, network errors and 5xx under one Idempotency-Key, so the
// provider returns the original charge instead of authorising a second one.
// 4xx (declines, bad input) are final. Worst case is three 10s timeouts plus
// back-off, about 32s.
async function charge(params) {
  const idempotencyKey = crypto.randomUUID();
  for (let attempt = 0; ; attempt++) {
    try {
      return await post(params, idempotencyKey);
    } catch (err) {
      const retryable = err.code !== undefined || err.status >= 500;
      if (!retryable || attempt === RETRY_DELAYS_MS.length) throw err;
      await sleep(RETRY_DELAYS_MS[attempt]);
    }
  }
}

function post({ amountCents, currency, customerId, source }, idempotencyKey) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            return reject(Object.assign(new Error(data), { status: res.statusCode }));
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () =>
      req.destroy(Object.assign(new Error("provider timeout"), { code: "ETIMEDOUT" }))
    );
    req.on("error", reject);
    req.end(body);
  });
}

module.exports = { charge };

