const assert = require("assert");
const { EventEmitter } = require("events");
const https = require("https");

// Each step drives one fake request: "timeout", or a [status, body] reply.
const keys = [];
let steps = [];
https.request = (opts, onResponse) => {
  keys.push(opts.headers["Idempotency-Key"]);
  const step = steps.shift();
  const req = new EventEmitter();
  req.destroy = (err) => req.emit("error", err);
  req.end = () =>
    process.nextTick(() => {
      if (step === "timeout") return req.emit("timeout");
      const res = new EventEmitter();
      res.statusCode = step[0];
      onResponse(res);
      res.emit("data", step[1]);
      res.emit("end");
    });
  return req;
};

const { charge } = require("./payments");

(async () => {
  steps = ["timeout", [200, '{"id":"ch_1"}']];
  assert.deepStrictEqual(await charge({}), { id: "ch_1" });
  assert.strictEqual(keys.length, 2);
  assert.strictEqual(keys[0], keys[1]);

  keys.length = 0;
  steps = [[402, "declined"]];
  await assert.rejects(charge({}), { status: 402 });
  assert.strictEqual(keys.length, 1);

  console.log("ok");
})();

