const https = require("https");

const PROVIDER = "api.cardstream.example";
const MAX_ATTEMPTS = 3;
const BASE_DELAY_MS = 500;

// A timeout, network error or 5xx leaves the outcome unknown (see PROVIDER.md),
// so those are retried with the same Idempotency-Key: if an earlier attempt did
// charge the card, the vendor returns that charge instead of authorising again.
// A 4xx other than 429 is a definite answer; it is thrown with `rejected` set
// and not retried.
async function charge(params) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await attemptCharge(params);
    } catch (err) {
      if (err.rejected || attempt === MAX_ATTEMPTS) throw err;
      const delay = BASE_DELAY_MS * 2 ** (attempt - 1);
      await new Promise((r) => setTimeout(r, delay / 2 + Math.random() * delay));
    }
  }
}

function attemptCharge({ amountCents, currency, customerId, source, idempotencyKey }) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            const err = new Error(data);
            err.rejected = res.statusCode < 500 && res.statusCode !== 429;
            return reject(err);
          }
          try {
            resolve(JSON.parse(data));
          } catch (err) {
            reject(err);
          }
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

module.exports = { charge };

