const crypto = require("crypto");
const express = require("express");
const db = require("../db");
const payments = require("../payments");

const router = express.Router();

router.post("/:orderId/pay", async (req, res) => {
  const rows = await db.query(
    "SELECT id, total_cents, currency, customer_id, status FROM orders WHERE id = $1",
    [req.params.orderId]
  );
  if (!rows.length) return res.status(404).end();
  const order = rows[0];
  if (order.status !== "pending" && order.status !== "charge_unknown") {
    return res.status(409).json({ status: order.status });
  }

  // The idempotency key is stored before the provider is called and kept until
  // the charge is settled, so a resubmit after a timeout, or a concurrent
  // double-click, sends the same key and cannot charge twice. The vendor only
  // honours a key for 24 hours; past that, reusing it is no longer safe and the
  // order has to be reconciled by hand.
  const claimed = await db.query(
    `UPDATE orders
        SET charge_key = COALESCE(charge_key, $2),
            charge_key_at = COALESCE(charge_key_at, now())
      WHERE id = $1 AND status IN ('pending', 'charge_unknown')
      RETURNING charge_key, charge_key_at > now() - interval '23 hours' AS key_fresh`,
    [order.id, crypto.randomUUID()]
  );
  if (!claimed.length) return res.status(409).end();
  const { charge_key: key, key_fresh: keyFresh } = claimed[0];
  if (!keyFresh) return res.status(202).json({ status: "processing" });

  try {
    const charge = await payments.charge({
      amountCents: order.total_cents,
      currency: order.currency,
      customerId: order.customer_id,
      source: req.body.source,
      idempotencyKey: key,
    });
    await db.query(
      "UPDATE orders SET status = 'paid', charge_id = $2 WHERE id = $1",
      [order.id, charge.id]
    );
    res.json({ status: "paid", charge: charge.id });
  } catch (err) {
    if (err.rejected) {
      // A definite no from the provider: nothing was charged. Drop the key so
      // the next attempt, possibly with another card, is a new charge.
      await db.query(
        `UPDATE orders SET status = 'pending', charge_key = NULL, charge_key_at = NULL
          WHERE id = $1 AND charge_key = $2`,
        [order.id, key]
      );
      return res.status(502).json({ error: "payment failed" });
    }
    // Retries ran out without an answer, or the charge succeeded and recording
    // it failed. The card may have been charged, so this is not a failure.
    await db.query(
      "UPDATE orders SET status = 'charge_unknown' WHERE id = $1 AND status = 'pending'",
      [order.id]
    );
    res.status(202).json({ status: "processing" });
  }
});

module.exports = router;

