const { client } = require("./redis");

// Requests allowed per client per window. Counted in the shared Redis, not in
// process memory, because each of the four workers on every box has its own
// heap - a module-scope counter would let a client through WORKERS x boxes
// times over. Keyed by client_id rather than IP: one client calls from many
// addresses, and unrelated clients share an address behind NAT.
const LIMIT = Number(process.env.RATE_LIMIT_PER_MINUTE) || 600;
const WINDOW_MS = 60_000;

// The increment and the expiry run as one script so a counter can never be
// left without a TTL and block its client forever.
client.defineCommand("rateLimitHit", {
  numberOfKeys: 1,
  lua: `
    local n = redis.call("INCR", KEYS[1])
    if n == 1 then redis.call("PEXPIRE", KEYS[1], ARGV[1]) end
    return {n, redis.call("PTTL", KEYS[1])}
  `,
});

// Must run after the auth middleware, which sets req.client.
async function rateLimit(req, res, next) {
  let count, ttlMs;
  try {
    [count, ttlMs] = await client.rateLimitHit(
      `rl:${req.client.client_id}`,
      WINDOW_MS
    );
  } catch (err) {
    // If Redis is unreachable, let the request through rather than turn a
    // limiter outage into an API outage.
    console.error("rate limit check failed", err);
    return next();
  }
  if (count > LIMIT) {
    res.set("Retry-After", String(Math.max(1, Math.ceil(ttlMs / 1000))));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit };

