const crypto = require("crypto");
const express = require("express");
const db = require("../db");
const payments = require("../payments");

const router = express.Router();

router.post("/:orderId/pay", async (req, res) => {
  const rows = await db.query(
    "SELECT id, total_cents, currency, customer_id, status FROM orders WHERE id = $1",
    [req.params.orderId]
  );
  if (!rows.length) return res.status(404).end();
  const order = rows[0];
  if (order.status !== "pending") return res.status(409).json({ status: order.status });

  // Same order and same source always give the same key, so a customer who
  // pays again after an unknown outcome gets the original charge back, not a
  // second one.
  const idempotencyKey = crypto
    .createHash("sha256")
    .update(`${order.id}:${JSON.stringify(req.body.source)}`)
    .digest("hex");

  try {
    const charge = await payments.charge({
      amountCents: order.total_cents,
      currency: order.currency,
      customerId: order.customer_id,
      source: req.body.source,
      idempotencyKey,
    });
    await db.query(
      "UPDATE orders SET status = 'paid', charge_id = $2 WHERE id = $1",
      [order.id, charge.id]
    );
    res.json({ status: "paid", charge: charge.id });
  } catch (err) {
    if (err.status) return res.status(502).json({ error: "payment failed" });
    // Retries ran out without an answer (or the UPDATE failed after a charge):
    // the money may have moved, so do not tell the customer it failed.
    res.status(504).json({ status: "unknown" });
  }
});

module.exports = router;

