// node test_payments.js — stubs https.request; no network.
const assert = require("assert");
const https = require("https");
const { EventEmitter } = require("events");

// Each entry is one attempt: "timeout", or [statusCode, body].
function stub(script) {
  const keys = [];
  https.request = (opts, onRes) => {
    keys.push(opts.headers["Idempotency-Key"]);
    const step = script.shift();
    const req = new EventEmitter();
    req.destroy = (err) => req.emit("error", err);
    req.end = () => setImmediate(() => {
      if (step === "timeout") return req.emit("timeout");
      const res = new EventEmitter();
      res.statusCode = step[0];
      onRes(res);
      res.emit("data", step[1]);
      res.emit("end");
    });
    return req;
  };
  return keys;
}

const { charge } = require("./payments");
const args = { amountCents: 100, currency: "usd", customerId: "c", source: "s", idempotencyKey: "k1" };

(async () => {
  let keys = stub(["timeout", "timeout", [200, '{"id":"ch_1"}']]);
  assert.strictEqual((await charge(args)).id, "ch_1");
  assert.deepStrictEqual(keys, ["k1", "k1", "k1"]);

  keys = stub(["timeout", "timeout", "timeout"]);
  await assert.rejects(charge(args), (e) => !e.status && /timeout/.test(e.message));
  assert.strictEqual(keys.length, 3);

  keys = stub([[402, "declined"]]);
  await assert.rejects(charge(args), (e) => e.status === 402);
  assert.strictEqual(keys.length, 1);

  console.log("ok");
})();

