const https = require("https");

const PROVIDER = "api.cardstream.example";
const ATTEMPTS = 3;
const BACKOFF_MS = [500, 2000];

// The vendor may or may not have authorised the charge (PROVIDER.md,
// "Timeouts"). This must never be reported to the customer as a failure.
class ChargeUnknownError extends Error {}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// One HTTP attempt. Only a 4xx other than 429 is a definitive answer; every
// other error leaves the outcome unknown.
function post(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("error", reject);
        res.on("end", () => {
          if (res.statusCode >= 400 && res.statusCode < 500 && res.statusCode !== 429) {
            return reject(Object.assign(new Error(data), { definitive: true }));
          }
          if (res.statusCode >= 400) return reject(new Error(data));
          try {
            resolve(JSON.parse(data));
          } catch (err) {
            reject(err);
          }
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

// Retrying is only safe because every attempt carries the same idempotency
// key: the vendor returns the original charge instead of authorising again.
async function charge({ amountCents, currency, customerId, source, idempotencyKey }) {
  if (!idempotencyKey) throw new Error("idempotencyKey is required");
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  let lastErr;
  for (let attempt = 0; attempt < ATTEMPTS; attempt++) {
    if (attempt) await sleep(BACKOFF_MS[attempt - 1]);
    try {
      return await post(body, idempotencyKey);
    } catch (err) {
      if (err.definitive) throw err;
      lastErr = err;
    }
  }
  throw new ChargeUnknownError(`charge outcome unknown after ${ATTEMPTS} attempts`, {
    cause: lastErr,
  });
}

module.exports = { charge, ChargeUnknownError };

