const crypto = require("crypto");
const express = require("express");
const db = require("../db");
const payments = require("../payments");

const router = express.Router();

router.post("/:orderId/pay", async (req, res) => {
  const rows = await db.query(
    "SELECT id, total_cents, currency, customer_id, status FROM orders WHERE id = $1",
    [req.params.orderId]
  );
  if (!rows.length) return res.status(404).end();
  const order = rows[0];
  if (order.status !== "pending") return res.status(409).json({ status: order.status });

  // The same order, amount and source always produce the same key, so a
  // customer who resubmits after an unknown outcome gets the original charge
  // back instead of being charged twice.
  const idempotencyKey = crypto
    .createHash("sha256")
    .update(JSON.stringify([order.id, order.total_cents, order.currency, req.body.source]))
    .digest("hex");

  try {
    const charge = await payments.charge({
      amountCents: order.total_cents,
      currency: order.currency,
      customerId: order.customer_id,
      source: req.body.source,
      idempotencyKey,
    });
    await db.query(
      "UPDATE orders SET status = 'paid', charge_id = $2 WHERE id = $1",
      [order.id, charge.id]
    );
    res.json({ status: "paid", charge: charge.id });
  } catch (err) {
    // The order stays pending; resubmitting with the same source replays the
    // same idempotency key and settles it.
    if (err instanceof payments.ChargeUnknownError) {
      console.error(`charge outcome unknown for order ${order.id}`, err.cause);
      return res.status(202).json({ status: "processing" });
    }
    res.status(502).json({ error: "payment failed" });
  }
});

module.exports = router;

