    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

// Retrying is only safe because every attempt carries the same idempotency
// key: the vendor returns the original charge instead of authorising again.
async function charge({ amountCents, currency, customerId, source, idempotencyKey }) {
  if (!idempotencyKey) throw new Error("idempotencyKey is required");
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  let lastErr;
  for (let attempt = 0; attempt < ATTEMPTS; attempt++) {
    if (attempt) await sleep(BACKOFF_MS[attempt - 1]);
    try {
      return await post(body, idempotencyKey);
    } catch (err) {
      if (err.definitive) throw err;
      lastErr = err;
    }
  }
  throw new ChargeUnknownError(`charge outcome unknown after ${ATTEMPTS} attempts`, {
    cause: lastErr,
  });
}

module.exports = { charge, ChargeUnknownError };

