const express = require('express');
const db = require('../db');

const router = express.Router();

// The CDN caches exactly what Cache-Control allows (see CDN.md). Shared caches
// keep a page for 60s and may serve it up to 30s stale while they refetch;
// browsers always revalidate. Stock is the most volatile thing on the page, so
// it sets the TTL rather than the catalogue edits.
const CACHE_CONTROL = 'public, max-age=0, s-maxage=60, stale-while-revalidate=30';

// Anonymous. No session is read here and nothing on the page varies by user -
// price, stock and copy are the same for everybody. Catalogue rows change when
// someone edits a product in the admin tool, which is a few times a day.
router.get('/:slug', async (req, res, next) => {
  const product = await db.productBySlug(req.params.slug);
  if (!product) return res.status(404).send('not found');
  const related = await db.relatedProducts(product.id);
  const stock = await db.stockFor(product.id);
  res.render('product', { product, related, stock }, (err, html) => {
    if (err) return next(err);
    // Only a successfully rendered page is marked cacheable; 404s and errors
    // keep the no-store default from the security middleware.
    res.set('Cache-Control', CACHE_CONTROL);
    res.removeHeader('Pragma');
    res.send(html);
  });
});

module.exports = router;

