ratelimit.js.text:
const { client: redis } = require("./redis");

// Counted per client account, not per key or address: one client can spread
// across many keys and IPs, and NAT puts several clients behind one IP. The
// counter lives in the shared Redis because each worker has its own heap.
const LIMIT = 600; // requests per client per window
const WINDOW_SECONDS = 60;

// ponytail: fixed window, so a client can burst up to 2x LIMIT across a window
// boundary; switch to a sliding window (sorted set or Lua) if that matters.
async function rateLimit(req, res, next) {
  const now = Math.floor(Date.now() / 1000);
  const key = `rl:${req.client.client_id}:${Math.floor(now / WINDOW_SECONDS)}`;
  let count;
  try {
    [[, count]] = await redis.multi().incr(key).expire(key, WINDOW_SECONDS).exec();
  } catch {
    return next(); // fail open: a Redis blip should not 429 every client
  }
  if (count > LIMIT) {
    res.set("Retry-After", String(WINDOW_SECONDS - (now % WINDOW_SECONDS)));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit, LIMIT };

