// Run: node ratelimit.test.js
const assert = require("assert");
const path = require("path");

const counts = new Map();
let down = false;
const fakeRedis = {
  multi() {
    let key;
    const tx = {
      incr: (k) => ((key = k), tx),
      expire: () => tx,
      exec: async () => {
        if (down) throw new Error("ECONNREFUSED");
        counts.set(key, (counts.get(key) || 0) + 1);
        return [[null, counts.get(key)], [null, 1]];
      },
    };
    return tx;
  },
};
require.cache[path.resolve(__dirname, "redis.js")] = { exports: { client: fakeRedis } };
const { rateLimit, LIMIT } = require("./ratelimit");

async function call(clientId) {
  const res = { status: 200, headers: {} };
  res.set = (k, v) => (res.headers[k] = v);
  res.status = (s) => ((res.code = s), { end() {} });
  let passed = false;
  await rateLimit({ client: { client_id: clientId } }, res, () => (passed = true));
  return { passed, code: res.code, retry: res.headers["Retry-After"] };
}

(async () => {
  for (let i = 0; i < LIMIT; i++) assert((await call("noisy")).passed);
  const blocked = await call("noisy");
  assert.strictEqual(blocked.code, 429);
  assert(Number(blocked.retry) > 0);
  assert((await call("quiet")).passed, "other clients unaffected");
  down = true;
  assert((await call("noisy")).passed, "fails open when Redis is down");
  console.log("ok");
})();

