const { client } = require("./redis");

// Counted in the shared Redis, not in process memory: a client's requests are
// spread over every worker on every box, so only a shared count sees them all.
// Keyed by client_id rather than API key or address, since one client can hold
// several keys and call from many addresses, and unrelated clients share NATs.
const LIMIT = Number(process.env.RATE_LIMIT_PER_MINUTE) || 600;
const WINDOW_SECONDS = 60;

// INCR and EXPIRE in one script so a counter can never be left without a TTL.
client.defineCommand("rateLimitHit", {
  numberOfKeys: 1,
  lua: `
    local n = redis.call("INCR", KEYS[1])
    if n == 1 then redis.call("EXPIRE", KEYS[1], ARGV[1]) end
    return {n, redis.call("TTL", KEYS[1])}
  `,
});

async function rateLimit(req, res, next) {
  let count, ttl;
  try {
    [count, ttl] = await client.rateLimitHit(`rl:${req.client.client_id}`, WINDOW_SECONDS);
  } catch (err) {
    // Fail open: a Redis outage should not take /v1 down with it.
    console.error("rate limit check failed", err);
    return next();
  }

  res.set("RateLimit-Limit", String(LIMIT));
  res.set("RateLimit-Remaining", String(Math.max(0, LIMIT - count)));
  res.set("RateLimit-Reset", String(ttl));

  if (count > LIMIT) {
    res.set("Retry-After", String(ttl));
    return res.status(429).json({ error: "rate limit exceeded" });
  }
  next();
}

module.exports = { rateLimit };

