const https = require("https");
const { setTimeout: sleep } = require("timers/promises");

const PROVIDER = "api.cardstream.example";
const ATTEMPTS = 3;

// Retries only when no response came back (timeout or dropped connection).
// Such a charge may or may not exist, so every attempt sends the same
// Idempotency-Key and the vendor returns the original charge instead of
// authorising again. If the last attempt also gets no response, the error
// carries outcomeUnknown: the customer may have been charged.
async function charge({ idempotencyKey, ...params }) {
  if (!idempotencyKey) throw new Error("idempotencyKey is required to retry safely");
  for (let attempt = 1; ; attempt++) {
    try {
      return await chargeOnce(params, idempotencyKey);
    } catch (err) {
      if (!err.outcomeUnknown || attempt === ATTEMPTS) throw err;
      await sleep(500 * attempt);
    }
  }
}

function chargeOnce({ amountCents, currency, customerId, source }, idempotencyKey) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) return reject(new Error(data));
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", (err) => {
      err.outcomeUnknown = true;
      reject(err);
    });
    req.end(body);
  });
}

module.exports = { charge };

