// Run: node payments.test.js
const assert = require("assert");
const https = require("https");
const { EventEmitter } = require("events");
const payments = require("./payments");

// Each outcome is "timeout" or { status, body }; returns the Idempotency-Key of each call.
function fakeProvider(outcomes) {
  const keys = [];
  https.request = (opts, onResponse) => {
    keys.push(opts.headers["Idempotency-Key"]);
    const outcome = outcomes.shift();
    const req = new EventEmitter();
    req.destroy = (err) => req.emit("error", err);
    req.end = () =>
      process.nextTick(() => {
        if (outcome === "timeout") return req.emit("timeout");
        const res = new EventEmitter();
        res.statusCode = outcome.status;
        onResponse(res);
        res.emit("data", JSON.stringify(outcome.body));
        res.emit("end");
      });
    return req;
  };
  return keys;
}

(async () => {
  const params = { amountCents: 500, currency: "usd", customerId: "c1", source: "tok", idempotencyKey: "k1" };

  let keys = fakeProvider(["timeout", "timeout", { status: 200, body: { id: "ch_1" } }]);
  assert.strictEqual((await payments.charge(params)).id, "ch_1");
  assert.deepStrictEqual(keys, ["k1", "k1", "k1"]);

  keys = fakeProvider([{ status: 402, body: { error: "declined" } }]);
  await assert.rejects(payments.charge(params), (err) => !err.outcomeUnknown);
