const crypto = require("crypto");
const https = require("https");

const PROVIDER = "api.cardstream.example";
const MAX_ATTEMPTS = 3;
const BACKOFF_MS = [250, 1000];

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Every attempt carries the same Idempotency-Key, so a retry after a timeout
// returns the original charge instead of authorising a second one. Timeouts,
// dropped connections and 5xx responses are retried; any other error is a
// definite answer and is thrown at once. If every attempt is inconclusive the
// error carries outcome "unknown": the charge may have been made.
async function charge({
  amountCents,
  currency,
  customerId,
  source,
  idempotencyKey = crypto.randomUUID(),
}) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  for (let attempt = 1; ; attempt++) {
    try {
      return await post(body, idempotencyKey);
    } catch (err) {
      if (!err.retryable) throw err;
      if (attempt >= MAX_ATTEMPTS) {
        err.outcome = "unknown";
        err.idempotencyKey = idempotencyKey;
        throw err;
      }
      await sleep(BACKOFF_MS[attempt - 1]);
    }
  }
}

function post(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          "Idempotency-Key": idempotencyKey,
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            const err = new Error(data);
            err.retryable = res.statusCode >= 500;
            return reject(err);
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", (err) => {
      err.retryable = true;
      reject(err);
    });
    req.end(body);
  });
}

module.exports = { charge };

