ratelimit.js.text:
const { client } = require("./redis");

// Counted per client account, not per IP: one client calls from many
// addresses and many clients share a NAT address. Counted in Redis because
// every worker on every box has its own heap.
const LIMIT = 600; // requests per client per window
const WINDOW_SECONDS = 60;

// ponytail: fixed window, so a client can burst to 2x LIMIT across a window
// boundary; move to a sliding window if that burst still hurts.
async function rateLimit(req, res, next) {
  const now = Math.floor(Date.now() / 1000);
  const key = `rl:${req.client.client_id}:${Math.floor(now / WINDOW_SECONDS)}`;
  let count;
  try {
    const [[, n]] = await client.multi().incr(key).expire(key, WINDOW_SECONDS).exec();
    count = n;
  } catch (err) {
    // Fail open: a Redis outage should not take /v1 down for everyone.
    console.error("rate limit skipped:", err.message);
    return next();
  }
  if (count > LIMIT) {
    res.set("Retry-After", String(WINDOW_SECONDS - (now % WINDOW_SECONDS)));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit, LIMIT };

