// node ratelimit.test.js — stubs ./redis, so no Redis or npm install needed.
const assert = require("assert");

const counts = new Map();
let redisDown = false;
require.cache[require.resolve("./redis")] = {
  exports: {
    client: {
      multi() {
        let key;
        const tx = {
          incr: (k) => ((key = k), tx),
          expire: () => tx,
          exec: async () => {
            if (redisDown) throw new Error("ECONNREFUSED");
            counts.set(key, (counts.get(key) || 0) + 1);
            return [[null, counts.get(key)], [null, 1]];
          },
        };
        return tx;
      },
    },
  },
};
const { rateLimit, LIMIT } = require("./ratelimit");

async function hit(clientId) {
  const res = { status: null, headers: {} };
  res.set = (k, v) => (res.headers[k] = v);
  res.status = (s) => ((res.code = s), { end() {} });
  let passed = false;
  await rateLimit({ client: { client_id: clientId } }, res, () => (passed = true));
  return { passed, code: res.code, retryAfter: res.headers["Retry-After"] };
}

(async () => {
  for (let i = 0; i < LIMIT; i++) assert((await hit("noisy")).passed);
  const blocked = await hit("noisy");
  assert.strictEqual(blocked.code, 429);
  assert(Number(blocked.retryAfter) > 0);
  assert((await hit("quiet")).passed, "other clients are unaffected");
  redisDown = true;
  assert((await hit("noisy")).passed, "fails open when Redis is down");
  console.log("ok");
})();

