const { client } = require("./redis");

// Fixed-window request budget per client account. The counter lives in the
// shared Redis, not in process memory, so every worker on every box draws on
// the same budget. It is keyed on client_id rather than IP, because one client
// calls from many addresses and many clients share one behind NAT.
const WINDOW_MS = 60_000;
const LIMIT = Number(process.env.RATE_LIMIT_PER_MINUTE) || 600;

// INCR and the expiry run as one script, so a crash between them can't leave
// behind a counter that never resets.
client.defineCommand("rateLimitHit", {
  numberOfKeys: 1,
  lua: `
    local n = redis.call("INCR", KEYS[1])
    if n == 1 then redis.call("PEXPIRE", KEYS[1], ARGV[1]) end
    return {n, redis.call("PTTL", KEYS[1])}
  `,
});

async function rateLimit(req, res, next) {
  let count, ttlMs;
  try {
    [count, ttlMs] = await client.rateLimitHit(`rl:${req.client.client_id}`, WINDOW_MS);
  } catch (err) {
    // Fail open: losing Redis shouldn't take /v1 down with it.
    return next();
  }
  res.set("RateLimit-Limit", String(LIMIT));
  res.set("RateLimit-Remaining", String(Math.max(0, LIMIT - count)));
  if (count > LIMIT) {
    res.set("Retry-After", String(Math.ceil(ttlMs / 1000)));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit };

