const https = require("https");
const { randomUUID } = require("crypto");
const { setTimeout: sleep } = require("timers/promises");

const PROVIDER = "api.cardstream.example";
const ATTEMPTS = 3;

// Every attempt carries the same Idempotency-Key, so retrying a charge that
// did go through returns that charge instead of authorising a second one.
// Timeouts, connection errors and 5xx are retried; 4xx (declines) are not.
// ponytail: worst case is ~32s of request time (3 x 10s timeout + backoff);
// move to a background job if the load balancer cuts requests sooner.
async function charge(params) {
  const idempotencyKey = randomUUID();
  for (let attempt = 1; ; attempt++) {
    try {
      return await chargeOnce(params, idempotencyKey);
    } catch (err) {
      const declined = err.status >= 400 && err.status < 500;
      if (declined || attempt === ATTEMPTS) throw err;
      await sleep(500 * attempt);
    }
  }
}

function chargeOnce({ amountCents, currency, customerId, source }, idempotencyKey) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            const err = new Error(data);
            err.status = res.statusCode;
            return reject(err);
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

module.exports = { charge };

