// Run: node payments.test.js
const assert = require("assert");
const https = require("https");
const { EventEmitter } = require("events");
const payments = require("./payments");

// Each queued outcome answers one https.request: "timeout" or a status code.
function stub(outcomes) {
  const keys = [];
  https.request = (opts, onResponse) => {
    keys.push(opts.headers["Idempotency-Key"]);
    const req = new EventEmitter();
    req.destroy = (err) => req.emit("error", err);
    req.end = () => {
      const outcome = outcomes.shift();
      if (outcome === "timeout") return req.emit("timeout");
      const res = new EventEmitter();
      res.statusCode = outcome;
      onResponse(res);
      res.emit("data", outcome < 400 ? '{"id":"ch_1"}' : "declined");
      res.emit("end");
    };
    return req;
  };
  return keys;
}

(async () => {
  // A timeout then success: retried once, under the same key.
  let keys = stub(["timeout", 200]);
  assert.deepStrictEqual(await payments.charge({}), { id: "ch_1" });
  assert.strictEqual(keys.length, 2);
  assert.strictEqual(keys[0], keys[1]);

  // A decline is not retried.
  keys = stub([402]);
  await assert.rejects(payments.charge({}), { status: 402 });
  assert.strictEqual(keys.length, 1);

  // Three timeouts give up.
  keys = stub(["timeout", "timeout", "timeout"]);
  await assert.rejects(payments.charge({}), /provider timeout/);
  assert.strictEqual(keys.length, 3);

  console.log("ok");
})();

