const crypto = require("crypto");
const https = require("https");

const PROVIDER = "api.cardstream.example";

const MAX_ATTEMPTS = 3;
const BASE_DELAY_MS = 500;

// One request to the provider. An error carries statusCode when the provider
// answered; without it, no response arrived (timeout, dropped connection) and
// the charge may or may not have been made.
function postCharge(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            const err = new Error(data);
            err.statusCode = res.statusCode;
            return reject(err);
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

function isRetryable(err) {
  return err.statusCode === undefined || err.statusCode === 429 || err.statusCode >= 500;
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Every attempt sends the same Idempotency-Key, so a retry after a timeout
// returns the original charge rather than authorising a second one. Declines
// and other 4xx responses are final. If the last attempt got no response, the
// error has outcome "unknown": the charge may exist.
async function charge({ amountCents, currency, customerId, source }) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  const idempotencyKey = crypto.randomUUID();
  for (let attempt = 1; ; attempt++) {
    try {
      return await postCharge(body, idempotencyKey);
    } catch (err) {
      if (attempt === MAX_ATTEMPTS || !isRetryable(err)) {
        err.outcome = err.statusCode === undefined ? "unknown" : "failed";
        throw err;
      }
      await sleep(BASE_DELAY_MS * 2 ** (attempt - 1) * (0.5 + Math.random()));
    }
  }
}

module.exports = { charge };

