const express = require('express');
const db = require('../db');

const router = express.Router();

// The CDN may keep a product page for a minute; browsers must revalidate with
// it. This overrides the app-wide no-store from security.js, so it is only
// safe while the page stays anonymous: no session, no Set-Cookie, nothing that
// varies by user.
const EDGE_CACHE = 'public, max-age=0, s-maxage=60, stale-while-revalidate=30';

// Anonymous. No session is read here and nothing on the page varies by user -
// price, stock and copy are the same for everybody. Catalogue rows change when
// someone edits a product in the admin tool, which is a few times a day.
router.get('/:slug', async (req, res, next) => {
  const product = await db.productBySlug(req.params.slug);
  if (!product) return res.status(404).send('not found');
  const related = await db.relatedProducts(product.id);
  const stock = await db.stockFor(product.id);
  // Mark the response cacheable only once it has rendered, so a 404 or a
  // render error is never stored at the edge.
  res.render('product', { product, related, stock }, (err, html) => {
    if (err) return next(err);
    res.set('Cache-Control', EDGE_CACHE);
    res.removeHeader('Pragma');
    res.send(html);
  });
});

module.exports = router;

