  query: async (sql, [p]) => (sql.includes("api_keys") ? [{ client_id: p, plan: "x" }] : []),
});

const hits = {}; // client_id -> count, ignoring the time bucket
const redis = {
  status: "ready",
  multi() {
    let key;
    const chain = {
      incr: (k) => ((key = k), chain),
      expire: () => chain,
      exec: async () => {
        const id = key.split(":")[1];
        hits[id] = (hits[id] || 0) + 1;
        return [[null, hits[id]], [null, 1]];
      },
    };
    return chain;
  },
};
stub("./redis", { client: redis });

const app = express();
app.use("/v1", require("./routes/api"));
const server = app.listen(0, async () => {
  const get = (key) =>
    fetch(`http://127.0.0.1:${server.address().port}/v1/reports`, { headers: { "X-Api-Key": key } });
  try {
    assert.equal((await get("a")).status, 200);

    hits.a = 1e9;
    const limited = await get("a");
    assert.equal(limited.status, 429);
    const retry = Number(limited.headers.get("retry-after"));
    assert.ok(retry >= 1 && retry <= 60, `Retry-After ${retry}`);

    assert.equal((await get("b")).status, 200, "other clients unaffected");

    redis.status = "reconnecting";
    assert.equal((await get("a")).status, 200, "fails open when Redis is down");

    console.log("ok");
  } finally {
    server.close();
  }
});

