const express = require("express");
const db = require("../db");
const { client: redis } = require("../redis");

const router = express.Router();

// Every request to /v1 carries an API key. Keys belong to a client account;
// one client may call from many addresses, and several clients share an
// address when they sit behind the same corporate NAT.
router.use(async (req, res, next) => {
  const key = req.get("X-Api-Key");
  if (!key) return res.status(401).end();
  const rows = await db.query(
    "SELECT client_id, plan FROM api_keys WHERE key = $1 AND revoked_at IS NULL",
    [key]
  );
  if (!rows.length) return res.status(401).end();
  req.client = rows[0];
  next();
});

// Per-client-account limit, counted in the shared Redis so it holds across
// every worker on every box. Keyed by client_id, not IP or key, for the
// reasons above.
// ponytail: fixed window lets a client burst up to 2x LIMIT across a window
// boundary; move to a sliding window if that burst still hurts.
const LIMIT = 600;
const WINDOW_SECONDS = 60;

router.use(async (req, res, next) => {
  // Fail open: /v1 never needed Redis before, so an outage must not take it down.
  if (redis.status !== "ready") return next();
  const now = Math.floor(Date.now() / 1000);
  const key = `rl:${req.client.client_id}:${Math.floor(now / WINDOW_SECONDS)}`;
  let count;
  try {
    [[, count]] = await redis.multi().incr(key).expire(key, WINDOW_SECONDS).exec();
  } catch {
    return next();
  }
  if (count > LIMIT) {
    res.set("Retry-After", String(WINDOW_SECONDS - (now % WINDOW_SECONDS)));
    return res.status(429).end();
  }
  next();
});

router.get("/reports", async (req, res) => {
  const rows = await db.query(
    "SELECT id, name, generated_at FROM reports WHERE client_id = $1 ORDER BY generated_at DESC LIMIT 100",
    [req.client.client_id]
  );
  res.json(rows);
});

router.post("/reports", async (req, res) => {
  const rows = await db.query(
    "INSERT INTO reports (client_id, name) VALUES ($1, $2) RETURNING id",
    [req.client.client_id, req.body.name]
  );
  res.status(201).json(rows[0]);
});

module.exports = router;

