ratelimit.js.text:
const { client } = require("./redis");

// Fixed-window request counter per client account. The count lives in the
// shared Redis, not in process memory, because each worker on each box has its
// own heap and would otherwise grant the client a separate budget.
//
// Keyed by client_id rather than API key or IP: one client may hold several
// keys and call from many addresses, and unrelated clients can share a NAT.
const LIMIT = Number(process.env.RATE_LIMIT_PER_MINUTE) || 600;
const WINDOW_SECONDS = 60;

async function rateLimit(req, res, next) {
  const nowSeconds = Math.floor(Date.now() / 1000);
  const window = Math.floor(nowSeconds / WINDOW_SECONDS);
  const key = `rl:${req.client.client_id}:${window}`;

  let count;
  try {
    const [[err, n]] = await client
      .multi()
      .incr(key)
      .expire(key, WINDOW_SECONDS)
      .exec();
    if (err) throw err;
    count = n;
  } catch (err) {
    // Fail open: a Redis outage should not take /v1 down for every client.
    return next();
  }

  res.set("X-RateLimit-Limit", String(LIMIT));
  res.set("X-RateLimit-Remaining", String(Math.max(0, LIMIT - count)));
  if (count > LIMIT) {
    res.set("Retry-After", String(WINDOW_SECONDS - (nowSeconds % WINDOW_SECONDS)));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit };

