const https = require("https");

const PROVIDER = "api.cardstream.example";
const ATTEMPTS = 3;

// Retries timeouts, network errors and 5xx. That is only safe because every
// attempt sends the same Idempotency-Key, so the vendor authorises at most once.
async function charge({ amountCents, currency, customerId, source, idempotencyKey }) {
  if (!idempotencyKey) throw new Error("charge() needs an idempotencyKey");
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  for (let attempt = 1; ; attempt++) {
    try {
      return await post(body, idempotencyKey);
    } catch (err) {
      const declined = err.status >= 400 && err.status < 500;
      if (declined || attempt === ATTEMPTS) throw err;
      await new Promise((r) => setTimeout(r, 500 * attempt));
    }
  }
}

function post(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            return reject(Object.assign(new Error(data), { status: res.statusCode }));
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

module.exports = { charge };

