const test = require("node:test");
const assert = require("node:assert");
const https = require("https");
const { EventEmitter } = require("events");
const payments = require("./payments");

// Each step is one attempt: "timeout", or [statusCode, body].
function fakeProvider(steps) {
  const keys = [];
  https.request = (opts, onResponse) => {
    keys.push(opts.headers["Idempotency-Key"]);
    const step = steps.shift();
    const req = new EventEmitter();
    req.destroy = (err) => req.emit("error", err);
    req.end = () =>
      setImmediate(() => {
        if (step === "timeout") return req.emit("timeout");
        const res = new EventEmitter();
        res.statusCode = step[0];
        onResponse(res);
        res.emit("data", step[1]);
        res.emit("end");
      });
    return req;
  };
  return keys;
}

const params = { amountCents: 500, currency: "usd", customerId: "c1", source: "card_1", idempotencyKey: "k1" };

test("retries timeouts with the same idempotency key", async () => {
  const keys = fakeProvider(["timeout", "timeout", [200, '{"id":"ch_1"}']]);
  assert.strictEqual((await payments.charge(params)).id, "ch_1");
  assert.deepStrictEqual(keys, ["k1", "k1", "k1"]);
});

test("does not retry a decline", async () => {
  const keys = fakeProvider([[402, "declined"]]);
  await assert.rejects(payments.charge(params), { status: 402 });
  assert.strictEqual(keys.length, 1);
});

test("gives up after three timeouts", async () => {
  const keys = fakeProvider(["timeout", "timeout", "timeout"]);
  await assert.rejects(payments.charge(params), { message: "provider timeout" });
  assert.strictEqual(keys.length, 3);
});

