const https = require("https");

const PROVIDER = "api.cardstream.example";
const MAX_ATTEMPTS = 3;
const BASE_DELAY_MS = 500;

// The provider answered with a 4xx other than 429: the charge was refused and
// nothing was authorised.
class ChargeRejectedError extends Error {
  constructor(statusCode, body) {
    super(body);
    this.statusCode = statusCode;
  }
}

// Every attempt timed out, dropped, or got a 5xx/429. PROVIDER.md says a
// timed-out charge may still have been made, so this is not a failure.
class ChargeOutcomeUnknownError extends Error {}

// Retries are only safe because every attempt carries the same
// Idempotency-Key: if an earlier attempt was authorised, the provider returns
// that charge instead of authorising a second one.
async function charge({ amountCents, currency, customerId, source, idempotencyKey }) {
  if (!idempotencyKey) throw new TypeError("charge() requires an idempotencyKey");
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  let lastErr;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return await send(body, idempotencyKey);
    } catch (err) {
      if (err instanceof ChargeRejectedError) throw err;
      lastErr = err;
      if (attempt < MAX_ATTEMPTS) {
        const delay = BASE_DELAY_MS * 2 ** (attempt - 1) * (0.5 + Math.random());
        await new Promise((r) => setTimeout(r, delay));
      }
    }
  }
  throw new ChargeOutcomeUnknownError(lastErr.message);
}

function send(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          "Idempotency-Key": idempotencyKey,
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 500 || res.statusCode === 429) return reject(new Error(data));
          if (res.statusCode >= 400) return reject(new ChargeRejectedError(res.statusCode, data));
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

module.exports = { charge, ChargeRejectedError, ChargeOutcomeUnknownError };

