      if (step === "reset") return req.emit("error", new Error("ECONNRESET"));
      const res = new EventEmitter();
      res.statusCode = step[0];
      cb(res);
      res.emit("data", step[1]);
      res.emit("end");
    });
    return req;
  };
  return seen;
}

