ratelimit.js.text:
const { client } = require("./redis");

// Per client account, not per IP or per key: one client calls from many
// addresses with many keys, and NAT puts several clients behind one address.
// Counted in Redis because the workers share nothing else.
const LIMIT = 600;
const WINDOW_SECONDS = 60;

// ponytail: fixed window, so a client can burst up to 2x LIMIT across a
// window boundary; switch to a sliding-window Lua script if that matters.
async function rateLimit(req, res, next) {
  const now = Math.floor(Date.now() / 1000);
  const key = `rl:${req.client.client_id}:${Math.floor(now / WINDOW_SECONDS)}`;
  let count;
  try {
    [[, count]] = await client.multi().incr(key).expire(key, WINDOW_SECONDS).exec();
  } catch (err) {
    // Fail open: a Redis blip should not take /v1 down for everyone.
    return next();
  }
  if (count > LIMIT) {
    res.set("Retry-After", String(WINDOW_SECONDS - (now % WINDOW_SECONDS)));
    return res.status(429).end();
  }
  next();
}

module.exports = rateLimit;
module.exports.LIMIT = LIMIT;

