// Run: node ratelimit.test.js  (no Redis needed; the client is faked)
const assert = require("assert");

const counts = new Map();
let redisDown = false;
const fakeClient = {
  multi() {
    let key;
    const tx = {
      incr: (k) => ((key = k), tx),
      expire: () => tx,
      exec: async () => {
        if (redisDown) throw new Error("ECONNREFUSED");
        counts.set(key, (counts.get(key) || 0) + 1);
        return [[null, counts.get(key)], [null, 1]];
      },
    };
    return tx;
  },
};
require.cache[require.resolve("./redis")] = { exports: { client: fakeClient } };
const rateLimit = require("./ratelimit");

async function call(clientId) {
  const res = { status: null, headers: {}, passed: false };
  res.set = (k, v) => (res.headers[k] = v);
  res.status = (code) => ({ end: () => (res.code = code) });
  await rateLimit({ client: { client_id: clientId } }, res, () => (res.passed = true));
  return res;
}

(async () => {
  for (let i = 0; i < rateLimit.LIMIT; i++) assert((await call(1)).passed);
  const blocked = await call(1);
  assert.strictEqual(blocked.code, 429);
  assert(Number(blocked.headers["Retry-After"]) > 0);
  assert((await call(2)).passed, "other clients unaffected");
  redisDown = true;
  assert((await call(1)).passed, "fails open when Redis is down");
  console.log("ok");
})();

