const { client } = require("./redis");

// Per-client request limit for /v1. The counter lives in Redis rather than in
// module scope so the limit holds across every worker on every box, and it is
// keyed on client_id rather than IP or API key because one client calls from
// many addresses and with many keys, while unrelated clients share NAT
// addresses.
const LIMIT = Number(process.env.RATE_LIMIT_REQUESTS) || 600;
const WINDOW_MS = Number(process.env.RATE_LIMIT_WINDOW_MS) || 60_000;

// INCR and PEXPIRE run as one script so a worker dying between them cannot
// leave a counter with no expiry, which would lock the client out for good.
client.defineCommand("rateLimitHit", {
  numberOfKeys: 1,
  lua: `
    local n = redis.call("INCR", KEYS[1])
    if n == 1 then redis.call("PEXPIRE", KEYS[1], ARGV[1]) end
    return {n, redis.call("PTTL", KEYS[1])}
  `,
});

async function rateLimit(req, res, next) {
  let count, ttlMs;
  try {
    [count, ttlMs] = await client.rateLimitHit(`rl:${req.client.client_id}`, WINDOW_MS);
  } catch (err) {
    // Fail open: a Redis outage should not take the whole API down with it.
    return next();
  }

  res.set("RateLimit-Limit", String(LIMIT));
  res.set("RateLimit-Remaining", String(Math.max(0, LIMIT - count)));
  res.set("RateLimit-Reset", String(Math.ceil(ttlMs / 1000)));

  if (count > LIMIT) {
    res.set("Retry-After", String(Math.ceil(ttlMs / 1000)));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit };

