const https = require("https");
const crypto = require("crypto");
const { setTimeout: sleep } = require("timers/promises");

const PROVIDER = "api.cardstream.example";
const ATTEMPTS = 3;

// Every attempt carries the same Idempotency-Key, so an attempt that timed out
// after the vendor charged is answered by the next one with the original charge
// instead of a second one (see PROVIDER.md). The key comes from the order and
// the request body, so a customer who clicks "pay" again with the same card
// after we give up also gets the original charge back.
async function charge({ orderId, amountCents, currency, customerId, source }) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  const key = crypto.createHash("sha256").update(`${orderId}:${body}`).digest("hex");
  for (let attempt = 1; ; attempt++) {
    try {
      return await post(body, key);
    } catch (err) {
      if (!err.retryable || attempt === ATTEMPTS) throw err;
      await sleep(500 * attempt);
    }
  }
}

function post(body, key) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": key,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            const err = new Error(data);
            err.retryable = res.statusCode >= 500;
            return reject(err);
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    // Timeouts and connection errors: the charge may or may not exist.
    req.on("error", (err) => {
      err.retryable = true;
      reject(err);
    });
    req.end(body);
  });
}

module.exports = { charge };

