// node test_payments.js
const assert = require("assert");
const https = require("https");
const { EventEmitter } = require("events");

let script = [];
const keys = [];
https.request = (opts, onRes) => {
  keys.push(opts.headers["Idempotency-Key"]);
  const step = script.shift();
  const req = new EventEmitter();
  req.destroy = (err) => req.emit("error", err);
  req.end = () =>
    setImmediate(() => {
      if (step === "timeout") return req.emit("timeout");
      const res = new EventEmitter();
      res.statusCode = step.status;
      onRes(res);
      res.emit("data", JSON.stringify(step.body));
      res.emit("end");
    });
  return req;
};

const payments = require("./payments");
const order = { orderId: 7, amountCents: 1000, currency: "eur", customerId: "c1", source: "tok" };

(async () => {
  // Timeout, then 5xx, then success: three attempts, one key.
  script = ["timeout", { status: 503, body: {} }, { status: 200, body: { id: "ch_1" } }];
  assert.deepStrictEqual(await payments.charge(order), { id: "ch_1" });
  assert.strictEqual(keys.length, 3);
  assert.strictEqual(new Set(keys).size, 1);

  // A decline is not retried.
  keys.length = 0;
  script = [{ status: 402, body: { error: "declined" } }];
  await assert.rejects(payments.charge(order), (err) => err.retryable === false);
  assert.strictEqual(keys.length, 1);

  // Timing out every time gives up after three attempts, marked retryable.
  keys.length = 0;
  script = ["timeout", "timeout", "timeout"];
  await assert.rejects(payments.charge(order), (err) => err.retryable === true);
  assert.strictEqual(keys.length, 3);

  console.log("ok");
})();

