const https = require("https");

const PROVIDER = "api.cardstream.example";
const MAX_ATTEMPTS = 3;
const BACKOFF_MS = [500, 1500];

// Every attempt carries the same Idempotency-Key, so a retry after a timeout
// returns the original charge instead of authorising again (PROVIDER.md).
async function charge({ idempotencyKey, ...params }) {
  if (!idempotencyKey) throw new Error("idempotencyKey is required");
  let lastErr;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return await attemptCharge(params, idempotencyKey);
    } catch (err) {
      if (!isRetryable(err)) throw err;
      lastErr = err;
      if (attempt < MAX_ATTEMPTS) await sleep(BACKOFF_MS[attempt - 1]);
    }
  }
  // No attempt got a definite answer, so the charge may exist. Callers must
  // not report this as a failure.
  lastErr.outcomeUnknown = true;
  throw lastErr;
}

// Timeouts and connection errors have no statusCode. A 4xx other than 429 is
// a definite answer (a decline, bad input) and is not retried.
function isRetryable(err) {
  return err.statusCode === undefined || err.statusCode === 429 || err.statusCode >= 500;
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function attemptCharge({ amountCents, currency, customerId, source }, idempotencyKey) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            const err = new Error(data);
            err.statusCode = res.statusCode;
            return reject(err);
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

module.exports = { charge };

