ratelimit.js.text:
const { client } = require("./redis");

// Counted per client account, not per IP: one client calls from many
// addresses, and unrelated clients share NAT addresses. Counted in the shared
// Redis, because every worker on every box has its own heap.
const LIMIT = 600; // requests per client per window
const WINDOW_SECONDS = 60;

// ponytail: fixed window, so a client can burst up to 2x LIMIT across a
// window boundary; move to a sliding window if that burst still hurts.
async function rateLimit(req, res, next) {
  const now = Math.floor(Date.now() / 1000);
  const key = `rl:${req.client.client_id}:${Math.floor(now / WINDOW_SECONDS)}`;
  let count;
  try {
    [[, count]] = await client.multi().incr(key).expire(key, WINDOW_SECONDS).exec();
  } catch (err) {
    // Fail open: a Redis hiccup should not become an outage for every client.
    return next();
  }
  if (count > LIMIT) {
    res.set("Retry-After", String(WINDOW_SECONDS - (now % WINDOW_SECONDS)));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit, LIMIT };

