// Run with: node ratelimit.test.js
const assert = require("assert");

// Stand-in for ./redis so the check runs without a Redis server.
const counts = new Map();
const fake = {
  multi() {
    const ops = [];
    const m = {
      incr: (k) => (ops.push(() => counts.set(k, (counts.get(k) || 0) + 1).get(k)), m),
      expire: () => (ops.push(() => 1), m),
      exec: async () => ops.map((op) => [null, op()]),
    };
    return m;
  },
};
const redisPath = require.resolve("./redis");
require.cache[redisPath] = { id: redisPath, filename: redisPath, loaded: true, exports: { client: fake } };

const { rateLimit, LIMIT } = require("./ratelimit");
Date.now = () => 1_700_000_010_000; // pin the window

async function call(clientId) {
  const res = { code: 200, headers: {} };
  res.set = (k, v) => (res.headers[k] = v);
  res.status = (c) => ((res.code = c), res);
  res.end = () => {};
  await rateLimit({ client: { client_id: clientId } }, res, () => {});
  return res;
}

(async () => {
  for (let i = 0; i < LIMIT; i++) assert.strictEqual((await call("noisy")).code, 200);
  const blocked = await call("noisy");
  assert.strictEqual(blocked.code, 429);
  assert.strictEqual(blocked.headers["Retry-After"], "30");
  assert.strictEqual((await call("quiet")).code, 200);
  console.log("ok");
})();

