const { client } = require("./redis");

// Requests are counted per client account in the shared Redis. A counter in
// module scope would be per worker process, so a client could get the limit
// once for every worker on every box.
const LIMIT = Number(process.env.RATE_LIMIT_PER_MINUTE) || 600;
const WINDOW_MS = 60 * 1000;

// INCR and PEXPIRE run as one atomic script, so a counter is never left
// behind without an expiry.
client.defineCommand("rateLimitHit", {
  numberOfKeys: 1,
  lua: `
    local count = redis.call("INCR", KEYS[1])
    if count == 1 then redis.call("PEXPIRE", KEYS[1], ARGV[1]) end
    return {count, redis.call("PTTL", KEYS[1])}
  `,
});

// Must run after authentication, since it keys on req.client.
async function rateLimit(req, res, next) {
  let count, ttlMs;
  try {
    [count, ttlMs] = await client.rateLimitHit(`rl:${req.client.client_id}`, WINDOW_MS);
  } catch (err) {
    // If Redis is unavailable, serve the request rather than fail all of /v1.
    return next();
  }
  res.set("RateLimit-Limit", String(LIMIT));
  res.set("RateLimit-Remaining", String(Math.max(0, LIMIT - count)));
  if (count > LIMIT) {
    res.set("Retry-After", String(Math.ceil(Math.max(ttlMs, 0) / 1000)));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit };

