const https = require("https");

const PROVIDER = "api.cardstream.example";
const ATTEMPTS = 3;

// Timeouts, network errors and 5xx are retried with the same Idempotency-Key,
// so a charge that went through on an earlier attempt is returned rather than
// made again. A 4xx is a definite answer and is thrown straight away.
async function charge(params) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await chargeOnce(params);
    } catch (err) {
      if ((err.status && err.status < 500) || attempt === ATTEMPTS) throw err;
      await new Promise((r) => setTimeout(r, 500 * attempt));
    }
  }
}

function chargeOnce({ amountCents, currency, customerId, source, idempotencyKey }) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            const err = new Error(data);
            err.status = res.statusCode;
            return reject(err);
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

module.exports = { charge };

