const assert = require("assert");
const https = require("https");
const { EventEmitter } = require("events");
const payments = require("./payments");

// Each request consumes one step: "timeout" or an HTTP status code.
let script;
let keys;
https.request = (opts, onResponse) => {
  keys.push(opts.headers["Idempotency-Key"]);
  const req = new EventEmitter();
  req.destroy = (err) => req.emit("error", err);
  req.end = () => {
    const step = script.shift();
    if (step === "timeout") return req.emit("timeout");
    const res = new EventEmitter();
    res.statusCode = step;
    onResponse(res);
    res.emit("data", JSON.stringify({ id: "ch_1" }));
    res.emit("end");
  };
  return req;
};

const params = { amountCents: 100, currency: "usd", customerId: "c", source: "s", idempotencyKey: "k" };

(async () => {
  script = ["timeout", "timeout", 200];
  keys = [];
  assert.strictEqual((await payments.charge(params)).id, "ch_1");
  assert.deepStrictEqual(keys, ["k", "k", "k"]);

  script = [402];
  keys = [];
  await assert.rejects(payments.charge(params), (err) => err.status === 402);
  assert.strictEqual(keys.length, 1);

  script = ["timeout", "timeout", "timeout"];
  keys = [];
  await assert.rejects(payments.charge(params), (err) => err.status === undefined);
  assert.strictEqual(keys.length, 3);

  console.log("ok");
})();

