const crypto = require("crypto");
const express = require("express");
const db = require("../db");
const payments = require("../payments");

const router = express.Router();

router.post("/:orderId/pay", async (req, res) => {
  const rows = await db.query(
    "SELECT id, total_cents, currency, customer_id, status FROM orders WHERE id = $1",
    [req.params.orderId]
  );
  if (!rows.length) return res.status(404).end();
  const order = rows[0];
  if (order.status !== "pending") return res.status(409).json({ status: order.status });

  // Same order and same source give the same key, so paying again after an
  // unknown outcome returns the original charge instead of making a second
  // one. A different card gets a new key.
  // ponytail: a declined card stays declined on this order for the vendor's
  // 24h key window; store a per-attempt key on the order if that bites.
  const idempotencyKey = crypto
    .createHash("sha256")
    .update(JSON.stringify([order.id, req.body.source]))
    .digest("hex");

  try {
    const charge = await payments.charge({
      amountCents: order.total_cents,
      currency: order.currency,
      customerId: order.customer_id,
      source: req.body.source,
      idempotencyKey,
    });
    await db.query(
      "UPDATE orders SET status = 'paid', charge_id = $2 WHERE id = $1",
      [order.id, charge.id]
    );
    res.json({ status: "paid", charge: charge.id });
  } catch (err) {
    if (err.status && err.status < 500) {
      return res.status(502).json({ error: "payment failed" });
    }
    // Timed out or 5xx on every attempt (or the UPDATE failed after a
    // charge): the card may have been charged, so this is not a failure.
    res.status(504).json({ status: "unknown" });
  }
});

module.exports = router;

