const https = require("https");

const PROVIDER = "api.cardstream.example";
const MAX_ATTEMPTS = 3;
const BACKOFF_MS = 500;

// Retrying is only safe because every attempt carries the same
// Idempotency-Key: the provider answers a repeat with the original charge
// instead of authorising again (see PROVIDER.md). Timeouts, connection errors,
// 5xx and 429 are retried; any other 4xx is a refusal and is thrown with
// `declined` set.
async function charge({ idempotencyKey, ...params }) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await postCharge(params, idempotencyKey);
