const crypto = require("crypto");
const express = require("express");
const db = require("../db");
const payments = require("../payments");

const router = express.Router();

router.post("/:orderId/pay", async (req, res) => {
  const rows = await db.query(
    "SELECT id, total_cents, currency, customer_id, status FROM orders WHERE id = $1",
    [req.params.orderId]
  );
  if (!rows.length) return res.status(404).end();
  const order = rows[0];
  if (order.status !== "pending") return res.status(409).json({ status: order.status });

  // Reuse the key a previous attempt left behind, if any. Paying again after
  // an unknown outcome then returns that charge rather than making a second
  // one, and concurrent submissions converge on a single key.
  const [{ payment_key: idempotencyKey }] = await db.query(
    "UPDATE orders SET payment_key = COALESCE(payment_key, $2) WHERE id = $1 RETURNING payment_key",
    [order.id, crypto.randomUUID()]
  );

  try {
    const charge = await payments.charge({
      amountCents: order.total_cents,
      currency: order.currency,
      customerId: order.customer_id,
      source: req.body.source,
      idempotencyKey,
    });
    await db.query(
      "UPDATE orders SET status = 'paid', charge_id = $2 WHERE id = $1",
      [order.id, charge.id]
    );
    res.json({ status: "paid", charge: charge.id });
  } catch (err) {
    if (!err.declined) {
      // Retries ran out, or recording the charge failed. Either way the
      // customer may have been charged, so this is not a failure; the key
      // stays on the order for the next attempt.
      return res.status(202).json({ status: "processing" });
    }
    // The provider refused the charge. Release the key so the next attempt,
    // perhaps with another card, is not answered with this same refusal.
    await db.query(
      "UPDATE orders SET payment_key = NULL WHERE id = $1 AND payment_key = $2",
      [order.id, idempotencyKey]
    );
    res.status(502).json({ error: "payment failed" });
  }
});

module.exports = router;

