const express = require('express');
const db = require('../db');

const router = express.Router();

// Product pages are identical for every visitor, so the CDN (which obeys only
// our headers, see CDN.md) may store them. This replaces the app-wide no-store
// from middleware/security.js for successful renders only; 404s and errors
// keep no-store. Browsers revalidate every time (max-age=0) and the edge holds
// a copy for 60s, so stock counts and admin edits show within about a minute.
//
// This is only safe while nothing on this route reads the session or sets a
// cookie. The edge does no cookie stripping, so a Set-Cookie sent with this
// header would be cached and handed to every visitor.
const CACHE_CONTROL = 'public, max-age=0, s-maxage=60, stale-while-revalidate=300';

// Anonymous. No session is read here and nothing on the page varies by user -
// price, stock and copy are the same for everybody. Catalogue rows change when
// someone edits a product in the admin tool, which is a few times a day.
router.get('/:slug', async (req, res) => {
  const product = await db.productBySlug(req.params.slug);
  if (!product) return res.status(404).send('not found');
  const related = await db.relatedProducts(product.id);
  const stock = await db.stockFor(product.id);
  res.set('Cache-Control', CACHE_CONTROL);
  res.removeHeader('Pragma');
  res.render('product', { product, related, stock });
});

module.exports = router;

