// Run: node ratelimit.test.js
const Module = require("module");
const assert = require("assert");

let redisDown = false;
const store = new Map();
class FakeRedis {
  multi() {
    const ops = [];
    const chain = {
      incr: (k) => (ops.push(() => store.set(k, (store.get(k) || 0) + 1).get(k)), chain),
      expire: () => (ops.push(() => 1), chain),
      exec: async () => {
        if (redisDown) throw new Error("connection lost");
        return ops.map((op) => [null, op()]);
      },
    };
    return chain;
  }
}
const handlers = [];
const fakes = {
  ioredis: FakeRedis,
  pg: { Pool: class {} },
  express: { Router: () => ({ use: (h) => handlers.push(h), get() {}, post() {} }) },
};
const load = Module._load;
Module._load = (name, ...rest) => (name in fakes ? fakes[name] : load(name, ...rest));

require("./routes/api");
const limiter = handlers[1];

async function call(clientId) {
  const res = { status: null, headers: {} };
  res.set = (k, v) => ((res.headers[k] = v), res);
  res.status = (c) => ((res.code = c), res);
  res.end = () => res;
  let passed = false;
  await limiter({ client: { client_id: clientId } }, res, () => (passed = true));
  return { passed, ...res };
}

(async () => {
  Date.now = () => 1_800_000_030_000; // 30s into a window
  for (let i = 0; i < 600; i++) assert((await call(1)).passed);
  const blocked = await call(1);
  assert.equal(blocked.passed, false);
  assert.equal(blocked.code, 429);
  assert.equal(blocked.headers["Retry-After"], "30");
  assert((await call(2)).passed, "other clients unaffected");

  Date.now = () => 1_800_000_060_000; // next window
  assert((await call(1)).passed, "limit resets");

  redisDown = true;
  assert((await call(1)).passed, "fails open");
  console.log("ok");
})();

redis.js.text:
const Redis = require("ioredis");

// The session store. One Redis, shared by every worker on every box - it is
// already the only piece of state the workers have in common.
const client = new Redis(process.env.REDIS_URL);

async function getSession(token) {
  const raw = await client.get(`sess:${token}`);
  return raw ? JSON.parse(raw) : null;
}

async function putSession(token, data, ttlSeconds) {
  await client.set(`sess:${token}`, JSON.stringify(data), "EX", ttlSeconds);
}

// Fixed-window request counter. The window number is in the key, so each
// window's count expires on its own and the next window starts from zero.
async function countRequest(id, windowSeconds) {
  const key = `rl:${id}:${Math.floor(Date.now() / 1000 / windowSeconds)}`;
  const [[, count]] = await client.multi().incr(key).expire(key, windowSeconds).exec();
  return count;
}

module.exports = { client, getSession, putSession, countRequest };

