const { client } = require("./redis");

// Counters live in the shared Redis, not in process memory: with four workers
// per box and several boxes, a per-process counter would let a client through
// at WORKERS x boxes times the limit.
const MAX = Number(process.env.RATE_LIMIT_MAX) || 600;
const WINDOW_MS = Number(process.env.RATE_LIMIT_WINDOW_MS) || 60_000;

// Fixed window. INCR and PEXPIRE run as one script so a key can never be left
// without an expiry, which would block the client forever.
client.defineCommand("rateLimitHit", {
  numberOfKeys: 1,
  lua: `
    local n = redis.call("INCR", KEYS[1])
    if n == 1 then redis.call("PEXPIRE", KEYS[1], ARGV[1]) end
    return { n, redis.call("PTTL", KEYS[1]) }
  `,
});

// Keyed on client_id, so it must run after the API key lookup. Not keyed on
// IP: one client calls from many addresses, and clients share NAT addresses.
async function rateLimit(req, res, next) {
  let count, ttlMs;
  try {
    [count, ttlMs] = await client.rateLimitHit(`rl:${req.client.client_id}`, WINDOW_MS);
  } catch (err) {
    // Fail open: a Redis outage should not take /v1 down for every client.
    console.error("rate limit check failed", err);
    return next();
  }

  const resetSeconds = Math.ceil(Math.max(ttlMs, 0) / 1000);
  res.set("RateLimit-Limit", String(MAX));
  res.set("RateLimit-Remaining", String(Math.max(MAX - count, 0)));
  res.set("RateLimit-Reset", String(resetSeconds));

  if (count > MAX) {
    res.set("Retry-After", String(resetSeconds));
    return res.status(429).end();
  }
  next();
}

