const https = require("https");
const { setTimeout: sleep } = require("timers/promises");

const PROVIDER = "api.cardstream.example";
const RETRY_DELAYS_MS = [500, 1000];

// A timeout or dropped connection leaves the charge's outcome unknown
// (PROVIDER.md), so it is retried. That is only safe because every attempt
// carries the same Idempotency-Key: the vendor returns the original charge
// instead of authorising again. An HTTP error response is a real answer and is
// not retried. If every attempt times out, the error is marked outcomeUnknown.
async function charge({ amountCents, currency, customerId, source, idempotencyKey }) {
  if (!idempotencyKey) throw new Error("idempotencyKey is required");
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  for (let attempt = 0; ; attempt++) {
    try {
      return await post(body, idempotencyKey);
    } catch (err) {
      if (err.statusCode) throw err;
      if (attempt === RETRY_DELAYS_MS.length) {
        err.outcomeUnknown = true;
        throw err;
      }
      await sleep(RETRY_DELAYS_MS[attempt]);
    }
  }
}

function post(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            return reject(Object.assign(new Error(data), { statusCode: res.statusCode }));
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

module.exports = { charge };

