// Run: node payments.test.js
const assert = require("assert");
const { EventEmitter } = require("events");
const https = require("https");

// Fake provider: the first `timeouts` requests time out, later ones answer `status`.
function fakeProvider(timeouts, status = 200) {
  const keys = [];
  https.request = (opts, onResponse) => {
    keys.push(opts.headers["Idempotency-Key"]);
    const req = new EventEmitter();
    req.destroy = (err) => req.emit("error", err);
    req.end = () =>
      setImmediate(() => {
        if (keys.length <= timeouts) return req.emit("timeout");
        const res = new EventEmitter();
        res.statusCode = status;
        onResponse(res);
        res.emit("data", JSON.stringify({ id: "ch_1" }));
        res.emit("end");
      });
    return req;
  };
  return keys;
}

const { charge } = require("./payments");
const args = { amountCents: 100, currency: "usd", customerId: "c", source: "s", idempotencyKey: "k" };

(async () => {
  let keys = fakeProvider(2);
  assert.deepStrictEqual(await charge(args), { id: "ch_1" });
  assert.deepStrictEqual(keys, ["k", "k", "k"]);

  keys = fakeProvider(3);
  await assert.rejects(charge(args), (e) => e.outcomeUnknown === true);
  assert.strictEqual(keys.length, 3);

  keys = fakeProvider(0, 402);
  await assert.rejects(charge(args), (e) => e.statusCode === 402 && !e.outcomeUnknown);
  assert.strictEqual(keys.length, 1);

  console.log("ok");
})();

