const crypto = require("crypto");
const express = require("express");
const db = require("../db");
const payments = require("../payments");

const router = express.Router();

router.post("/:orderId/pay", async (req, res) => {
  const rows = await db.query(
    "SELECT id, total_cents, currency, customer_id, status FROM orders WHERE id = $1",
    [req.params.orderId]
  );
  if (!rows.length) return res.status(404).end();
  const order = rows[0];
  if (order.status !== "pending") return res.status(409).json({ status: order.status });

  // Same order, amount and card always give the same key, so retries and
  // repeat clicks get the original charge back instead of a second one.
  const idempotencyKey = crypto
    .createHash("sha256")
    .update(`${order.id}:${order.total_cents}:${order.currency}:${req.body.source}`)
    .digest("hex");

  try {
    const charge = await payments.charge({
      amountCents: order.total_cents,
      currency: order.currency,
      customerId: order.customer_id,
      source: req.body.source,
      idempotencyKey,
    });
    await db.query(
      "UPDATE orders SET status = 'paid', charge_id = $2 WHERE id = $1",
      [order.id, charge.id]
    );
    res.json({ status: "paid", charge: charge.id });
  } catch (err) {
    // Every attempt timed out, so the charge may have gone through. Paying
    // again with the same card is safe: it returns the original charge.
    if (err.outcomeUnknown) return res.status(504).json({ status: "unknown" });
    res.status(502).json({ error: "payment failed" });
  }
});

module.exports = router;

