const crypto = require("crypto");
const https = require("https");

const PROVIDER = "api.cardstream.example";
const MAX_ATTEMPTS = 3;
const BACKOFF_MS = [500, 1500];

// A timed-out charge may or may not have been made (see PROVIDER.md), so
// every attempt for one charge carries the same Idempotency-Key. If an earlier
// attempt did authorise, the provider returns that charge instead of making a
// second one. Only outcomes that are not a definite answer are retried.
async function charge({
  amountCents,
  currency,
  customerId,
  source,
  idempotencyKey = crypto.randomUUID(),
}) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  for (let attempt = 1; ; attempt++) {
    try {
      return await post(body, idempotencyKey);
    } catch (err) {
      if (!err.retryable || attempt === MAX_ATTEMPTS) throw err;
      await new Promise((r) => setTimeout(r, BACKOFF_MS[attempt - 1]));
    }
  }
}

function post(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 400) {
            const err = new Error(data);
            // A 4xx such as a decline is final; 429 and 5xx are not.
            err.retryable = res.statusCode === 429 || res.statusCode >= 500;
            return reject(err);
          }
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", (err) => {
      // Timeouts and dropped connections leave the outcome unknown.
      err.retryable = true;
      reject(err);
    });
    req.end(body);
  });
}

module.exports = { charge };

