const { client } = require("./redis");

// Counters live in the shared Redis, not in module scope: each client's
// requests are spread over every worker on every box, so a per-process
// counter would let them through at WORKERS x boxes times the limit.
const LIMIT = Number(process.env.RATE_LIMIT_PER_WINDOW) || 600;
const WINDOW_MS = Number(process.env.RATE_LIMIT_WINDOW_MS) || 60_000;

// Fixed window. INCR and the expiry are set in one script so a crash between
// them cannot leave a counter that never expires.
client.defineCommand("rateLimitHit", {
  numberOfKeys: 1,
  lua: `
    local n = redis.call("INCR", KEYS[1])
    if n == 1 then redis.call("PEXPIRE", KEYS[1], ARGV[1]) end
    return {n, redis.call("PTTL", KEYS[1])}
  `,
});

// Keyed by client account, not by API key or address: a client may hold
// several keys and call from many addresses, and unrelated clients share
// addresses behind NAT. Must run after the auth middleware sets req.client.
async function rateLimit(req, res, next) {
  let count, ttl;
  try {
    [count, ttl] = await client.rateLimitHit(
      `rl:${req.client.client_id}`,
      WINDOW_MS
    );
  } catch (err) {
    // Fail open: a Redis outage should not take /v1 down for every client.
    return next();
  }

  res.set("X-RateLimit-Limit", String(LIMIT));
  res.set("X-RateLimit-Remaining", String(Math.max(0, LIMIT - count)));
  if (count > LIMIT) {
    res.set("Retry-After", String(Math.ceil(Math.max(ttl, 0) / 1000)));
    return res.status(429).end();
  }
  next();
}

module.exports = { rateLimit };

