const crypto = require("crypto");
const https = require("https");

const PROVIDER = "api.cardstream.example";
const ATTEMPTS = 3;

// Timeouts, dropped connections and 5xx are retried under one Idempotency-Key,
// so the provider never authorises the same charge twice. A 4xx is a definite
// answer and is not retried. An error with outcomeUnknown may still have
// charged the card (see PROVIDER.md); err.idempotencyKey replays the real
// result for 24 hours.
async function charge({ amountCents, currency, customerId, source }) {
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  const idempotencyKey = crypto.randomUUID();
  for (let attempt = 1; ; attempt++) {
    try {
      return await post(body, idempotencyKey);
    } catch (err) {
      if (!err.outcomeUnknown || attempt === ATTEMPTS) {
        err.idempotencyKey = idempotencyKey;
        throw err;
      }
      await new Promise((r) => setTimeout(r, 500 * attempt));
    }
  }
}

function post(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const unknown = (err) => {
      err.outcomeUnknown = true;
      reject(err);
    };
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
          "Idempotency-Key": idempotencyKey,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => {
          if (res.statusCode >= 500) return unknown(new Error(data));
          if (res.statusCode >= 400) return reject(new Error(data));
          resolve(JSON.parse(data));
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", unknown);
    req.end(body);
  });
}

module.exports = { charge };

