// node payments.test.js
const assert = require("assert");
const https = require("https");
const { EventEmitter } = require("events");
const payments = require("./payments");

// Each outcome is "timeout" or an HTTP status. Returns the keys sent.
function fakeProvider(outcomes) {
  const keys = [];
  https.request = (opts, onRes) => {
    keys.push(opts.headers["Idempotency-Key"]);
    const req = new EventEmitter();
    req.destroy = (err) => req.emit("error", err);
    req.end = () =>
      setImmediate(() => {
        const o = outcomes.shift();
        if (o === "timeout") return req.emit("timeout");
        const res = new EventEmitter();
        res.statusCode = o;
        onRes(res);
        res.emit("data", JSON.stringify({ id: "ch_1" }));
        res.emit("end");
      });
    return req;
  };
  return keys;
}

const order = { amountCents: 100, currency: "usd", customerId: "c", source: "s" };

(async () => {
  let keys = fakeProvider(["timeout", 503, 200]);
  assert.strictEqual((await payments.charge(order)).id, "ch_1");
  assert.strictEqual(keys.length, 3);
  assert.strictEqual(new Set(keys).size, 1);

  keys = fakeProvider([402]);
  let err = await payments.charge(order).catch((e) => e);
  assert.ok(!err.outcomeUnknown);
  assert.strictEqual(keys.length, 1);

  keys = fakeProvider(["timeout", "timeout", "timeout"]);
  err = await payments.charge(order).catch((e) => e);
  assert.ok(err.outcomeUnknown);
  assert.strictEqual(err.idempotencyKey, keys[0]);
  assert.strictEqual(keys.length, 3);

  console.log("ok");
})();

