const https = require("https");
const { setTimeout: sleep } = require("timers/promises");

const PROVIDER = "api.cardstream.example";
const MAX_ATTEMPTS = 3;
const BACKOFF_MS = [500, 1500];

// The provider answered and the answer is no (a 4xx other than 429). No charge
// exists under the idempotency key, so retrying with it would only replay this.
class ChargeDeclined extends Error {}

function postCharge(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          "Idempotency-Key": idempotencyKey,
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("error", reject);
        res.on("end", () => {
          if (res.statusCode === 429 || res.statusCode >= 500) {
            return reject(new Error(`provider ${res.statusCode}: ${data}`));
          }
          if (res.statusCode >= 400) return reject(new ChargeDeclined(data));
          try {
            resolve(JSON.parse(data));
          } catch (err) {
            reject(err);
          }
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

// Retries timeouts, network errors, 429 and 5xx. Every attempt carries the same
// Idempotency-Key, so the provider authorises at most once however many
// attempts reach it. Anything thrown other than ChargeDeclined means the
// outcome is unknown: the card may have been charged.
async function charge({ amountCents, currency, customerId, source, idempotencyKey }) {
  if (!idempotencyKey) throw new Error("idempotencyKey is required");
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  for (let attempt = 1; ; attempt++) {
    try {
      return await postCharge(body, idempotencyKey);
    } catch (err) {
      if (err instanceof ChargeDeclined || attempt === MAX_ATTEMPTS) throw err;
      await sleep(BACKOFF_MS[attempt - 1]);
    }
  }
}

module.exports = { charge, ChargeDeclined };

