const https = require("https");
const { setTimeout: sleep } = require("timers/promises");

const PROVIDER = "api.cardstream.example";
const MAX_ATTEMPTS = 3;
const BACKOFF_MS = [500, 1500];

// The provider answered and the answer is no (a 4xx other than 429). No charge
// exists under the idempotency key, so retrying with it would only replay this.
class ChargeDeclined extends Error {}

function postCharge(body, idempotencyKey) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        host: PROVIDER,
        path: "/v2/charges",
        method: "POST",
        timeout: 10000,
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          "Idempotency-Key": idempotencyKey,
          Authorization: `Bearer ${process.env.CARDSTREAM_KEY}`,
        },
      },
      (res) => {
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("error", reject);
        res.on("end", () => {
          if (res.statusCode === 429 || res.statusCode >= 500) {
            return reject(new Error(`provider ${res.statusCode}: ${data}`));
          }
          if (res.statusCode >= 400) return reject(new ChargeDeclined(data));
          try {
            resolve(JSON.parse(data));
          } catch (err) {
            reject(err);
          }
        });
      }
    );
    req.on("timeout", () => req.destroy(new Error("provider timeout")));
    req.on("error", reject);
    req.end(body);
  });
}

// Retries timeouts, network errors, 429 and 5xx. Every attempt carries the same
// Idempotency-Key, so the provider authorises at most once however many
// attempts reach it. Anything thrown other than ChargeDeclined means the
// outcome is unknown: the card may have been charged.
async function charge({ amountCents, currency, customerId, source, idempotencyKey }) {
  if (!idempotencyKey) throw new Error("idempotencyKey is required");
  const body = JSON.stringify({
    amount: amountCents,
    currency,
    customer: customerId,
    source,
  });
  for (let attempt = 1; ; attempt++) {
    try {
      return await postCharge(body, idempotencyKey);
    } catch (err) {
      if (err instanceof ChargeDeclined || attempt === MAX_ATTEMPTS) throw err;
      await sleep(BACKOFF_MS[attempt - 1]);
    }
  }
}

module.exports = { charge, ChargeDeclined };

const crypto = require("crypto");
const express = require("express");
const db = require("../db");
const payments = require("../payments");

const router = express.Router();

router.post("/:orderId/pay", async (req, res) => {
  const rows = await db.query(
    "SELECT id, total_cents, currency, customer_id, status FROM orders WHERE id = $1",
    [req.params.orderId]
  );
  if (!rows.length) return res.status(404).end();
  const order = rows[0];
  if (order.status !== "pending") return res.status(409).json({ status: order.status });

  // An attempt whose outcome is unknown leaves its key on the order. Reusing it
  // means a second click replays that charge instead of making another, and two
  // concurrent requests for one order share a key.
  const keyed = await db.query(
    `UPDATE orders SET payment_key = COALESCE(payment_key, $2)
      WHERE id = $1 AND status = 'pending' RETURNING payment_key`,
    [order.id, crypto.randomUUID()]
  );
  if (!keyed.length) return res.status(409).end();
  const key = keyed[0].payment_key;

  try {
    const charge = await payments.charge({
      amountCents: order.total_cents,
      currency: order.currency,
      customerId: order.customer_id,
      source: req.body.source,
      idempotencyKey: key,
    });
    await db.query(
      "UPDATE orders SET status = 'paid', charge_id = $2 WHERE id = $1",
      [order.id, charge.id]
    );
    res.json({ status: "paid", charge: charge.id });
  } catch (err) {
    if (!(err instanceof payments.ChargeDeclined)) {
      // Retries ran out, or something failed after the charge went through.
      // The card may have been charged, so this is not a failure; the key
      // stays on the order for the next attempt to resolve it.
      return res.status(202).json({ status: "processing" });
    }
    // A definite decline: clear the key so another card gets a fresh charge.
    await db.query(
      "UPDATE orders SET payment_key = NULL WHERE id = $1 AND payment_key = $2",
      [order.id, key]
    );
    res.status(502).json({ error: "payment failed" });
  }
});

module.exports = router;

