mkdir -p /tmp/retrytest && cat > /tmp/retrytest/test.js <<'EOF'
const https = require("https");
const { EventEmitter } = require("events");
const assert = require("assert");

let script = [], seen = [];
https.request = (opts, cb) => {
  const req = new EventEmitter();
  req.destroy = (err) => setImmediate(() => req.emit("error", err));
  req.end = () => {
    seen.push(opts.headers["Idempotency-Key"]);
    const step = script.shift();
    setImmediate(() => {
      if (step === "timeout") return req.emit("timeout");
      const res = new EventEmitter();
      res.statusCode = step.status;
      cb(res);
      res.emit("data", step.body);
      res.emit("end");
    });
  };
  return req;
};

const payments = require(process.argv[2]);
const args = { amountCents: 100, currency: "usd", customerId: "c", source: "s", idempotencyKey: "k1" };

(async () => {
  script = ["timeout", { status: 503, body: "" }, { status: 200, body: '{"id":"ch_1"}' }]; seen = [];
  assert.deepStrictEqual(await payments.charge(args), { id: "ch_1" });
  assert.deepStrictEqual(seen, ["k1", "k1", "k1"]);

  script = ["timeout", "timeout", "timeout", { status: 200, body: "{}" }]; seen = [];
  await assert.rejects(payments.charge(args), (e) => !(e instanceof payments.ChargeDeclined) && e.message === "provider timeout");
  assert.strictEqual(seen.length, 3);

  script = [{ status: 402, body: "declined" }, { status: 200, body: "{}" }]; seen = [];
  await assert.rejects(payments.charge(args), payments.ChargeDeclined);
  assert.strictEqual(seen.length, 1);

  await assert.rejects(payments.charge({ ...args, idempotencyKey: undefined }), /required/);
  console.log("ok");
})();
EOF
node /tmp/retrytest/test.js /tmp/tmprs_cnnve/payments.js && node --check /tmp/tmprs_cnnve/routes/checkout.js && echo syntax-ok
